package com.library.reader; import com.baomidou.mybatisplus.core.mapper.BaseMapper; import org.apache.ibatis.annotations.*; import java.util.*; @Mapper public interface ReaderMapper extends BaseMapper<Reader>{@Select("SELECT r.*,u.real_name,u.phone,u.email FROM reader r LEFT JOIN sys_user u ON r.user_id=u.id WHERE r.deleted=0 AND (#{k}='' OR r.reader_no LIKE CONCAT('%',#{k},'%') OR u.real_name LIKE CONCAT('%',#{k},'%')) ORDER BY r.id DESC LIMIT #{o},#{s}")List<Map<String,Object>>search(String k,long o,long s);@Select("SELECT COUNT(*) FROM reader r LEFT JOIN sys_user u ON r.user_id=u.id WHERE r.deleted=0 AND (#{k}='' OR r.reader_no LIKE CONCAT('%',#{k},'%') OR u.real_name LIKE CONCAT('%',#{k},'%'))")long count(String k);}
